\item[S2] Nikita Kalinin and Mikhail Shkolnikov, \emph{The number $\pi$ and summation by $SL(2,\mathbb Z)$}, Arnold Mathematical Journal (2018) \S4, Questions, pp. 5--6. \url{https://amj.math.stonybrook.edu/html-articles/Files-2015-2024/17-75/index.html}.
\end{description}
